struct TrieNode {
    TrieNode* children[26] = {};   // fixed array: fast, lowercase only
    bool isWord = false;           // does a word END here?
};

class Trie {
    TrieNode* root = new TrieNode();
public:
    void insert(const string& word) {
        TrieNode* node = root;
        for (char ch : word) {
            int i = ch - 'a';
            if (!node->children[i]) node->children[i] = new TrieNode();
            node = node->children[i];
        }
        node->isWord = true;       // mark the end
    }

    TrieNode* walk(const string& prefix) {
        TrieNode* node = root;
        for (char ch : prefix) {
            node = node->children[ch - 'a'];
            if (!node) return nullptr;
        }
        return node;
    }

    bool search(const string& word) {
        TrieNode* n = walk(word);
        return n && n->isWord;     // BOTH conditions
    }

    bool startsWith(const string& prefix) {
        return walk(prefix) != nullptr;
    }
};

