    let node = this.root;
    for (const ch of prefix) {
      node = node.children.get(ch);
      if (!node) return null;
    }
    return node;
  }

  search(word) {
    const n = this.#walk(word);
    return !!n && n.isWord;      // BOTH conditions
  }

  startsWith(prefix) {
    return this.#walk(prefix) !== null;
  }
